def main():
    path = ROOT / "materials/twenty-complete-DEEN-cases.author.json"
    data = json.loads(path.read_text())
    changes = []
    for case, answer in zip(data["cases"], ANSWERS_DE, strict=True):
        case["modelAnswerDe"] = answer
        for field in ("materialDe", "taskDemandDe", "materialEn", "taskDemandEn"):
            old = case[field]
            for before, after in REPLACEMENTS.items():
                case[field] = case[field].replace(before, after)
            if old != case[field]:
                changes.append({"caseId": case["id"], "field": field, "kind": "explicit spacing repairs"})
        for criterion in case["rubric"]:
            for field in ("fullCreditDe", "fullCreditEn"):
                for before, after in REPLACEMENTS.items():
                    criterion[field] = criterion[field].replace(before, after)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n")
    audit = ROOT / "AUTHOR.material-reuse-and-explicit-changes.json"
    value = json.loads(audit.read_text())
    value["readabilitySuccessor"] = {"wholeGermanModelAnswersReworded": 20, "scientificClaimsRetained": True, "oldExactCasesPreserved": True, "explicitSpacingRepairs": changes}
    audit.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n")
    print(json.dumps({"readableGermanAnswers": 20, "spacingFields": len(changes), "oldCasesChanged": 0}))


if __name__ == "__main__":
    main()
